import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Listen,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { nav, remove } from "../../../icons";
import { focusVisible } from "../../utils/focus-visible";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

/**
 * @since 0.0.11
 * @status experimental
 *
 * @slot nav - Used for grouping tabs in the tab group.
 * @slot - Used for grouping tab panels in the tab group.
 *
 * @part base - The component's base wrapper.
 * @part nav - The tab group navigation container.
 * @part tabs - The container that wraps the slotted tabs.
 * @part active-tab-indicator - An element that displays the currently selected tab. This is a child of the tabs container.
 * @part body - The tab group body where tab panels are slotted in.
 */

@Component({
	tag: "hbr-tab-vertical",
	styleUrl: "tab-vertical.scss",
	shadow: true,
})
export class TabVertical {
	/** Enables and shows the collapse button */
	@Prop({ reflect: true }) collapsable = false;

	/** Enables drag resizing */
	@Prop({ reflect: true }) resizable = false;

	/** Current width applied to the component */
	@Prop({ mutable: true, reflect: true }) width = 250;

	/** Minimum allowed width when resizing */
	@Prop() minWidth = 120;

	/** Maximum allowed width when resizing */
	@Prop() maxWidth = 360;

	sheet: CSSStyleSheet = new CSSStyleSheet();
	activeTab: HTMLHbrTabElement;
	activeTabIndicator: HTMLElement;
	body: HTMLElement;
	mutationObserver: MutationObserver;
	navEle: HTMLElement;
	resizeObserver: ResizeObserver;
	tabVertical: HTMLElement;
	tabs: HTMLElement;

	@State() isVisible = false;

	@State() hasTopSlot = false;

	private handleTopSlotChange = (event: Event) => {
		const slot = event.target as HTMLSlotElement;
		this.hasTopSlot = slot.assignedNodes({ flatten: true }).length > 0;
	};

	@Element() host: HTMLHbrTabVerticalElement;

	/** @deprecated It's deprecated since v2.0.0. */
	@Prop({ reflect: true }) navigation = false;

	@Prop({ reflect: true }) variant: "nested" | "tab" | "" = "";

	/** Emitted when a tab is shown. */
	@Event({ eventName: "hbr-tab-show" }) hbrTabShow: EventEmitter<{
		name: string;
	}>;

	/** Emitted when a tab is hidden. */
	@Event({ eventName: "hbr-tab-hide" }) hbrTabHide: EventEmitter<{
		name: string;
	}>;

	/** @deprecated */
	@Prop({ mutable: true, reflect: true }) sentiment = "interact";

	/** Enable tab border */
	@Prop({ reflect: true }) border = false;

	/** make this component uncontrolled */
	@Prop() uncontrolled = false;

	/** @deprecated make this component responsive */
	@Prop({ reflect: true }) responsive = false;

	/** role */
	@Prop({ reflect: true }) ariarole: string;

	/** arialabel */
	@Prop({ reflect: true }) arialabel: string | boolean = false;

	/** Vertical tabs in collapsed state */
	@Prop({ reflect: true, mutable: true }) collapsed = false;

	/** Attributes related to screen readers. */
	@Prop() aria: { role?: string; label?: string };

	@Listen("hbr-select")
	menuItemListener(e: CustomEvent) {
		const target = e.target as HTMLElement;
		const popover = target.closest("hbr-tab-popover");
		if (popover instanceof HTMLElement) {
			const tab = popover.shadowRoot.querySelector("hbr-tab");
			if (tab) {
				this.setActiveTab(tab);
			}
		}
	}

	connectedCallback() {
		this.handleClick = this.handleClick.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.getAllTabs = this.getAllTabs.bind(this);
		this.setActiveTab = this.setActiveTab.bind(this);
		this.getAllTabFold = this.getAllTabFold.bind(this);
		this.handleClickIcon = this.handleClickIcon.bind(this);
	}

	componentDidLoad() {
		this.syncCollapsedOfTabs();
		// Set initial tab state when the tabs first become visible
		const observer = new IntersectionObserver((entries, observer) => {
			if (entries[0].intersectionRatio > 0) {
				this.setAriaLabels();
				if (!this.navigation) {
					if (!this.uncontrolled) {
						this.setActiveTab(
							this.getActiveTab() || this.getAllTabs()[0],
							false,
						);
					}
				}
				observer.unobserve(entries[0].target);
			}
		});
		observer.observe(this.host);

		focusVisible.observe(this.tabVertical);

		// Update aria labels if the DOM changes
		this.mutationObserver = new MutationObserver((mutations) => {
			if (
				mutations.some((mutation) => {
					return !["aria-labelledby", "aria-controls"].includes(
						mutation.attributeName,
					);
				})
			) {
				setTimeout(() => this.setAriaLabels());
			}
		});
		this.mutationObserver.observe(this.host, {
			attributes: true,
			childList: true,
			subtree: true,
		});
	}

	disconnectedCallback() {
		this.mutationObserver?.disconnect();
		focusVisible.unobserve(this.tabVertical);
		this.resizeObserver?.unobserve(this.navEle);
	}

	/** Shows the specified tab panel. */
	@Method()
	async show(panel: string) {
		const tabs = this.getAllTabs();
		const tab = tabs.find((el) => el.panel === panel);

		if (tab) {
			this.setActiveTab(tab);
		}
	}

	@Watch("collapsed")
	syncCollapsedOfTabs() {
		if (this.collapsable) return;
		this.host.querySelectorAll("hbr-tab").forEach((tab) => {
			tab.collapsed = this.collapsed;
		});
	}

	getAllTabs(includeDisabled = false, ele?, isAll = true) {
		let slot = ele;
		if (!ele) slot = this.tabs?.querySelector("slot");
		if (!slot) return [];
		const slotList = [...slot.assignedElements({ flatten: true })];
		const tabList = slotList.reduce((acc, cur) => {
			if (cur.tagName.toLowerCase() === "hbr-tab" && !cur.disabled)
				acc.push(cur);
			if (cur.tagName.toLowerCase() === "hbr-tab-fold" && !cur.disabled) {
				acc.push(cur);
				if (cur.open || isAll) {
					const slot = cur?.shadowRoot?.querySelector(
						"slot:not([name='label'])",
					);
					if (slot) acc.push(...this.getAllTabs(includeDisabled, slot));
				}
			}
			if (cur.tagName.toLowerCase() === "hbr-tab-popover") {
				const tab = cur?.shadowRoot.querySelector("hbr-tab");
				if (tab) {
					acc.push(tab);
				}
			}
			return acc;
		}, []);
		return tabList;
	}

	getAllPanels() {
		const slot = this.body?.querySelector("slot");
		if (!slot) return [];
		return [...slot.assignedElements()].filter(
			(el: HTMLElement) => el.tagName.toLowerCase() === "hbr-tab-panel",
		) as [HTMLHbrTabPanelElement];
	}

	getAllTabFold() {
		const slot = this.tabs?.querySelector("slot");
		if (!slot) return [];
		return [...slot.assignedElements()].filter(
			(el: HTMLElement) => el.tagName.toLowerCase() === "hbr-tab-fold",
		) as [HTMLHbrTabFoldElement];
	}

	getActiveTab() {
		return this.getAllTabs().find((el) => el.active);
	}

	handleClick(event: MouseEvent) {
		if (this.uncontrolled) return;
		const target = event.target as HTMLElement;
		const tab = target.closest("hbr-tab");
		const tabVertical = tab?.closest("hbr-tab-vertical");
		// Ensure the target tab is in this tab group
		if (tabVertical !== this.host) {
			return false;
		}

		if (tab) {
			this.setActiveTab(tab);
		}
		this.isVisible = !this.isVisible;
	}

	handleClickIcon() {
		this.isVisible = !this.isVisible;
	}

	getOrientation() {
		return this.host.getAttribute("aria-orientation") === "horizontal"
			? "horizontal"
			: "vertical";
	}

	handleKeyDown(event: KeyboardEvent) {
		if (this.uncontrolled) return;
		const target = event.target as HTMLElement;
		const tab = target.closest("hbr-tab");
		const tabFold = target.closest("hbr-tab-fold");
		let tabVertical = tab?.closest("hbr-tab-vertical");
		if (tabFold) {
			tabVertical = tabFold?.closest("hbr-tab-vertical");
		}
		// Ensure the target tab is in this tab group
		if (tabVertical !== this.host) {
			return false;
		}

		// Activate a tab
		if (["Enter", " "].includes(event.key)) {
			if (tab) {
				if (this.uncontrolled) return;
				this.setActiveTab(tab);
				event.preventDefault();
				this.isVisible = false;
			}
		}

		const orientation = this.getOrientation();
		const prevKey = orientation === "horizontal" ? "ArrowLeft" : "ArrowUp";
		const nextKey = orientation === "horizontal" ? "ArrowRight" : "ArrowDown";

		// Move focus across tabs based on orientation
		if ([prevKey, nextKey, "Home", "End"].includes(event.key)) {
			const activeEl = document.activeElement;
			if (!activeEl) return;
			const isTab =
				activeEl.closest("hbr-tab") || activeEl.closest("hbr-tab-fold");
			if (isTab) {
				const tabs = this.getAllTabs(false, false, false);
				let index = tabs.indexOf(isTab);

				if (event.key === "Home") {
					index = 0;
				} else if (event.key === "End") {
					index = tabs.length - 1;
				} else if (event.key === prevKey) {
					index = Math.max(0, index - 1);
				} else if (event.key === nextKey) {
					index = Math.min(tabs.length - 1, index + 1);
				}

				const tab = tabs[index];
				tab.setFocus({ preventScroll: true });

				event.preventDefault();
			}
		}
	}

	setActiveTab(tab: HTMLHbrTabElement, emitEvents = true) {
		const isNestedTab = tab?.closest("hbr-tab-panel");
		if (isNestedTab && this.host.contains(isNestedTab)) return;
		if (tab && tab !== this.activeTab && !tab.disabled) {
			const previousTab = this.activeTab;
			this.activeTab = tab;

			// Sync tabs and panels
			this.getAllTabs().map((el) => {
				el.active = el === this.activeTab;
			});
			this.getAllTabFold().forEach((el) => {
				if (el.contains(tab) && !el.open) el.active = true;
				else el.active = false;
			});
			this.getAllPanels().map((el) => {
				el.active = el.name === this.activeTab.panel;
			});

			// Emit events
			if (emitEvents) {
				if (previousTab) {
					this.hbrTabHide.emit({ name: previousTab.panel });
				}

				this.hbrTabShow.emit({ name: this.activeTab.panel });
			}
		}
	}

	setAriaLabels() {
		if (this.variant === "nested") return;
		const tabs = this.getAllTabs();
		const panels = this.getAllPanels();

		// Link each tab with its corresponding panel
		tabs.map((tab: HTMLHbrTabElement) => {
			const panel = panels.find((el) => el.name === tab.panel);
			if (panel) {
				const tabId = tab.getAttribute("id");
				const panelId = panel.getAttribute("id");
				panelId && tab.setAttribute("aria-controls", panelId);
				tabId && panel.setAttribute("aria-labelledby", tabId);
			}
		});
	}

	isTab = () => {
		return ["tab", "nested"].includes(this.variant);
	};

	@Method()
	async getTabs() {
		return this._getTabs();
	}

	@Method()
	async getTabFolds() {
		return this._getTabFolds();
	}

	_getTabs = () => {
		return Array.from(
			this.host.querySelectorAll("hbr-tab:not(hbr-tab-panel hbr-tab)"),
		) as HTMLHbrTabElement[];
	};

	_getTabFolds = () => {
		return Array.from(
			this.host.querySelectorAll(
				"hbr-tab-fold:not(hbr-tab-panel hbr-tab-fold)",
			),
		) as HTMLHbrTabFoldElement[];
	};

	handleSlotChange = () => {
		const tabs = this._getTabs();
		const tabFolds = this._getTabFolds();

		tabs.forEach((tab) => {
			tab.vertical = true;
			if (this.variant === "nested") {
				tab.aria = { role: "treeitem" };
			}
		});

		if (this.variant === "nested") {
			tabFolds.forEach((tabFold) => {
				tabFold.setAttribute("role", "treeitem");
			});
		}

		const divider = this.host.querySelector(
			"hbr-divider:not(hbr-tab-panel hbr-divider)",
		);
		if (divider) {
			divider.setAttribute("aria-hidden", "true");
		}
	};

	handleContentSlotChange = () => {
		if (!["tab", "nested"].includes(this.variant)) return;

		const panels = Array.from(
			this.host.querySelectorAll(':scope > hbr-tab-panel[slot="content"]'),
		) as HTMLHbrTabPanelElement[];

		panels.forEach((panel) => {
			panel.ariarole = false;
		});
	};

	private conditionalPanel = (children: HTMLElement) => {
		if (this.collapsable || this.resizable) {
			return (
				<hbr-panel
					part="panel"
					collapsable={this.collapsable}
					resizable={this.resizable}
					collapsed={this.collapsed}
					size={this.width}
					minSize={this.minWidth}
					maxSize={this.maxWidth}
					onHbr-panel-resizing={(e: CustomEvent<{ size: number }>) => {
						this.host.style.setProperty("--min-width", `${e.detail.size}px`);
					}}
				>
					{children}
				</hbr-panel>
			);
		}
		return children;
	};

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;

		return (
			<Host>
				<div
					part="base"
					ref={(el) => {
						this.tabVertical = el;
					}}
					class={{
						"tab-vertical": true,
						"tab-vertical--collapsed": !this.collapsable && this.collapsed,
						"tab-vertical--resizable": this.resizable,
					}}
				>
					<hbr-icon-button
						class={{
							"tab-vertical__menu-icon": true,
							"tab-vertical__menu-icon-no-responsive": !this.responsive,
						}}
						onClick={this.handleClickIcon}
						asset={customSystemIcons?.nav || nav}
						arialabel="Open menu"
					/>
					{this.conditionalPanel(
						<div
							class={{
								"tab-vertical__nav-container": !this.isTab(),
								"tab-visible": this.isVisible,
								"tab-vertical__nav-container-no-responsive": !this.responsive,
							}}
							part="nav-container"
						>
							<div class={{ "tab-vertical__top": this.hasTopSlot }}>
								<slot name="top" onSlotchange={this.handleTopSlotChange} />
							</div>
							<hbr-icon-button
								class={{
									"tab-vertical__close-icon": true,
									"tab-vertical__close-icon-no-responsive": !this.responsive,
								}}
								onClick={this.handleClickIcon}
								asset={customSystemIcons?.remove || remove}
								arialabel="Close menu"
							/>
							<div part="prefix" class="tab-vertical__prefix">
								<slot name="prefix" />
							</div>
							<div
								ref={(el) => {
									this.navEle = el;
								}}
								key="nav"
								part="nav"
								class="tab-vertical__nav"
							>
								<div
									ref={(el) => {
										this.tabs = el;
									}}
									part="tabs"
									class={{
										"tab-vertical__tabs": true,
										"tab-vertical__tabs-nav": this.navigation,
									}}
									{...(this.aria?.role === "none" //stepper
										? undefined
										: {
												role:
													this.variant === "nested"
														? "tree"
														: this.ariarole || this.navigation
														  ? "menubar"
														  : "tablist",

												"aria-orientation": "vertical",
										  })}
									aria-label={this.arialabel}
									onClick={this.handleClick}
									onKeyDown={this.handleKeyDown}
								>
									<slot onSlotchange={this.handleSlotChange} />
								</div>
							</div>
							<div part="suffix" class="tab-vertical__suffix">
								<slot name="suffix" />
							</div>
						</div>,
					)}

					{!this.resizable && !this.collapsable && (
						<span
							part="border"
							class={{
								"tab-vertical__resizer": true,
								"tab-vertical__resizer-border": this.border,
							}}
						/>
					)}

					<div
						ref={(el) => {
							this.body = el;
						}}
						part="body"
						class="tab-vertical__body"
					>
						<slot name="content" onSlotchange={this.handleContentSlotChange} />
					</div>
				</div>
			</Host>
		);
	}
}
